 const supported=Boolean(data?.enabled&&data.platforms.includes('linux'));
 const collectionProfile=data?enrollmentCollectionProfile(data):null;
 const records=data?.items.filter(item=>all||!terminal(item.state))||[];
 const pending=data?.items.filter(item=>item.state==='claimed_pending').length||0;
